  else
    sed -i '/maps_hg_hook.js/a <script src="maps_s1_hook.js"></script>' index.html
  fi
fi

echo "---- تحقق ----"
ls -l s1_data.js lessons_as1_sci.js maps_s1.html maps_s1_hook.js
grep -n 's1_data.js\|lessons_as1_sci.js\|maps_s1_hook.js' index.html
echo "تم. نسخة احتياطية: index.html.bak_s1"
